class Solution {
public:
    long long minSum(vector<int>& nums1, vector<int>& nums2) {
        long long s1 = 0, s2 = 0;
        int z1 = 0, z2 = 0;
        for (int x : nums1) {
            if (x == 0) { s1 += 1; z1++; }
            else s1 += x;
        }
        for (int x : nums2) {
            if (x == 0) { s2 += 1; z2++; }
            else s2 += x;
        }
        if (s1 == s2) return s1;
        if (s1 < s2) {
            if (z1 > 0) return s2;
            return -1;
        } else {
            if (z2 > 0) return s1;
            return -1;
        }
    }
};
